fn main() {
    let steps: usize = std::env::args().nth(1).and_then(|s| s.parse().ok()).unwrap_or(2000);
    let t = std::time::Instant::now();
    match ::vox::morphism_factor::factor_bounded(N_WORD, steps) {
        Ok(w) => {
            let f = ::vox::morphism_factor::parse_numeral(&w).unwrap();
            println!("FACTOR WORD: {}", w);
            println!("FACTOR(decoded): {}", ::vox::morphism_factor::dec_of(&f));
        }
        Err(e) => println!("READOUT ({:.3}s, steps={}): {}", t.elapsed().as_secs_f64(), steps, e),
    }
}
